"use client"

import { useSearchParams, useRouter } from "next/navigation"
import { Button } from "@/components/ui/button"
import { ArrowLeft, Smartphone, User, Heart, MessageCircle, Share2, MoreVertical, QrCode, Copy } from "lucide-react"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import Image from "next/image"
import { useState, useEffect, Suspense } from "react"

function ViewerContent() {
  const searchParams = useSearchParams()
  const router = useRouter()
  
  const [networkIp, setNetworkIp] = useState<string>("localhost")
  const [isPublicUrl, setIsPublicUrl] = useState<boolean>(false)
  const [publicIp, setPublicIp] = useState<string>("")
  const [shareUrl, setShareUrl] = useState<string>("")
  const [isShareModalOpen, setIsShareModalOpen] = useState(false)
  const [imageId, setImageId] = useState<string | null>(null)

  const [imageData, setImageData] = useState<string | null>(null)
  const [loading, setLoading] = useState(true)
  const width = parseInt(searchParams.get("width") || "690", 10)
  const label = searchParams.get("label") || "미리보기"

  useEffect(() => {
    fetch('/api/network-ip')
      .then(res => res.json())
      .then(data => {
        if (data.ip) {
          setNetworkIp(data.ip)
          setIsPublicUrl(data.isPublic || false)
          if (data.publicIp) setPublicIp(data.publicIp)
        }
      })
      .catch(console.error)
  }, [])

  useEffect(() => {
    const id = searchParams.get("id")
    
    // 네트워크로 접속한 모바일 기기에서도 볼 수 있도록 API에서 이미지 URL 직접 사용 (용량 초과 및 터널 브라우저 멈춤/로딩 무한 루프 방지)
    if (id) {
      setImageId(id)
      setImageData(`/api/image?id=${id}`) // 브라우저 <img src>로 직접 로딩하여 로컬터널 payload 한계 우회
      setLoading(false)
      return
    }

    // sessionStorage에서 fallback 이미지 데이터 로드 (PC 접속자용)
    const storedImage = sessionStorage.getItem("scrollViewerImage")
    if (storedImage) {
      setImageData(storedImage)
    }
    setLoading(false)
  }, [searchParams])

  const handleShareMobile = async () => {
    let currentImageId = imageId;
    // 이미지 ID가 없는 경우(세션스토리지 기반 접속), 새로운 ID를 만들어서 서버에 올려줌
    if (!currentImageId && imageData) {
      currentImageId = Date.now().toString() + Math.random().toString(36).substring(2)
      try {
        await fetch('/api/image', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ id: currentImageId, data: imageData })
        })
        setImageId(currentImageId)
      } catch (err) {
        console.error('Failed to link image', err)
      }
    }

    const params = new URLSearchParams({
      width: width.toString(),
      label: label,
      id: currentImageId || ""
    })
    
    let mobileUrl = "";
    if (isPublicUrl) {
      mobileUrl = `${networkIp}/mobile-scroll/viewer?${params.toString()}`
    } else {
      const port = window.location.port ? `:${window.location.port}` : ''
      mobileUrl = `http://${networkIp}${port}/mobile-scroll/viewer?${params.toString()}`
    }
    
    setShareUrl(mobileUrl)
    setIsShareModalOpen(true)
  }

  const copyToClipboard = async () => {
    try {
      await navigator.clipboard.writeText(shareUrl)
      alert("모바일용 링크가 복사되었습니다!\n카카오톡 등으로 스마트폰에 보내거나 QR 코드를 스캔하세요.")
    } catch {
      alert("복사에 실패했습니다.")
    }
  }

  if (loading) {
    return (
      <div className="flex min-h-screen flex-col items-center justify-center gap-4 p-8">
        <p className="text-muted-foreground animate-pulse">이미지를 불러오는 중...</p>
        <p className="text-xs text-slate-400">네트워크 환경에 따라 시간이 걸릴 수 있습니다.</p>
      </div>
    )
  }

  if (!imageData) {
    return (
      <div className="flex min-h-screen flex-col items-center justify-center gap-4 p-8">
        <p className="text-muted-foreground">이미지 링크가 만료되었거나 이미지가 없습니다.</p>
        <Button onClick={() => window.close()} variant="outline" className="gap-2">
          <ArrowLeft className="h-4 w-4" />
          창 닫기
        </Button>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-background">
      <header className="sticky top-0 z-40 border-b border-border bg-background/95 backdrop-blur">
        <div className="mx-auto flex max-w-4xl items-center justify-between px-4 py-4">
          <div className="flex items-center gap-3">
            <Smartphone className="h-6 w-6 text-primary" />
            <div>
              <h1 className="text-lg font-semibold text-foreground">
                {label} 웹툰 뷰어
              </h1>
              <p className="text-sm text-muted-foreground">모바일 가로 {width}px 기준</p>
            </div>
          </div>
          <div className="flex gap-2">
            <Button onClick={handleShareMobile} variant="outline" className="gap-2 bg-indigo-50 text-indigo-700 hover:bg-indigo-100 hover:text-indigo-800 border border-indigo-200">
              <QrCode className="h-4 w-4" />
              <span className="hidden sm:inline">폰으로 보기</span>
            </Button>
            <Button onClick={() => window.close()} variant="outline" className="gap-2">
              <ArrowLeft className="h-4 w-4" />
              창 닫기
            </Button>
          </div>
        </div>
      </header>

      <main className="mx-auto py-8 px-4" style={{ maxWidth: width + 32 }}>
        <div 
          className="mx-auto overflow-hidden rounded-xl border border-border bg-card shadow-sm"
          style={{ width: "100%", maxWidth: width }}
        >
          {/* 업로드한 작품 원본 이미지 */}
          <div className="w-full">
            {imageData && (
              <img
                src={imageData}
                alt={`${label} 미리보기`}
                className="h-auto w-full object-contain block m-0 p-0"
                style={{ width: "100%" }}
              />
            )}
          </div>
        </div>
      </main>

      <Dialog open={isShareModalOpen} onOpenChange={setIsShareModalOpen}>
        <DialogContent className="sm:max-w-md flex flex-col items-center justify-center p-8">
          <DialogHeader className="w-full text-center">
            <DialogTitle className="text-xl">스마트폰으로 접속하기</DialogTitle>
            <DialogDescription>
              스마트폰 카메라로 QR 코드를 스캔하세요.
            </DialogDescription>
          </DialogHeader>

          <div className="my-6 rounded-xl bg-white p-4 shadow-sm border border-slate-100 flex justify-center w-full">
            {shareUrl ? (
              <img
                src={`https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(shareUrl)}`}
                alt="QR Code"
                width={200}
                height={200}
                className="rounded-lg object-contain w-[200px] h-[200px]"
              />
            ) : (
              <div className="w-[200px] h-[200px] bg-slate-100 rounded-lg animate-pulse" />
            )}
          </div>

          <p className="text-sm text-center text-muted-foreground w-full break-all mb-4 px-4 py-2 bg-secondary rounded-md">
            {shareUrl}
          </p>

          <div className="flex w-full gap-3 sm:flex-row flex-col justify-center">
            <Button onClick={copyToClipboard} variant="outline" className="gap-2">
              <Copy className="h-4 w-4" />
              링크 복사
            </Button>
            <Button onClick={() => setIsShareModalOpen(false)}>
              닫기
            </Button>
          </div>

          {publicIp && (
            <div className="mt-6 w-full rounded-lg bg-orange-50 p-4 text-sm text-orange-900 border border-orange-200">
              <span className="block font-bold mb-1 text-orange-950">⚠️ 초기 보안 화면 통과 방법</span>
              스마트폰 화면에 IP 입력칸이 나오면 아래의 IP(비밀번호)를 입력하고 <strong className="bg-orange-100 px-1 rounded">Submit</strong> 을 누르세요.
              <div className="mt-2 text-center text-lg font-mono font-bold tracking-widest text-orange-600 bg-white py-2 rounded border border-orange-100">
                {publicIp}
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>
    </div>
  )
}

export default function MobileScrollViewerPage() {
  return (
    <Suspense fallback={
      <div className="flex min-h-screen items-center justify-center">
        <p className="text-muted-foreground">로딩 중...</p>
      </div>
    }>
      <ViewerContent />
    </Suspense>
  )
}
